package rpg.engine.render.desktop;
import rpg.engine.render.Renderer;import org.lwjgl.glfw.*;import org.lwjgl.opengl.*;import static org.lwjgl.glfw.GLFW.*;import static org.lwjgl.opengl.GL11.*;
public final class LwjglRenderer implements Renderer {private long window;private int width,height;public LwjglRenderer(int w,int h,String title){if(!glfwInit())throw new IllegalStateException("GLFW init failed");glfwDefaultWindowHints();glfwWindowHint(GLFW_VISIBLE,GLFW_TRUE);window=glfwCreateWindow(w,h,title,0,0);if(window==0)throw new IllegalStateException("window creation failed");glfwMakeContextCurrent(window);GL.createCapabilities();glfwSwapInterval(1);width=w;height=h;}public boolean shouldClose(){return glfwWindowShouldClose(window);}public void poll(){glfwPollEvents();}public void begin(int w,int h){width=w;height=h;glViewport(0,0,w,h);glClearColor(.06f,.06f,.07f,1);glClear(GL_COLOR_BUFFER_BIT);}public void tile(int x,int y,int id){double sx=(x-y)*16.0,sy=(x+y)*8.0;glBegin(GL_QUADS);glColor3f(.18f+.03f*(id%3),.22f,.18f);glVertex2d(sx,sy);glVertex2d(sx+16,sy+8);glVertex2d(sx,sy+16);glVertex2d(sx-16,sy+8);glEnd();}public void sprite(double x,double y,double elevation,int resource){double sx=(x-y)*16,sy=(x+y)*8-elevation*8;glBegin(GL_QUADS);glColor3f(.8f,.7f,.3f);glVertex2d(sx-8,sy-20);glVertex2d(sx+8,sy-20);glVertex2d(sx+8,sy);glVertex2d(sx-8,sy);glEnd();}public void end(){glfwSwapBuffers(window);}public void close(){if(window!=0)glfwDestroyWindow(window);glfwTerminate();}}
